// check-docs <folder>: the knowledge base's checks on a folder (default: the
// current one). Prints each problem with its file and line, and exits with 1
// when there is any.
import { checkDocs } from "../src/index.js";
const root = process.argv[2] ?? ".";
const problems = await checkDocs(root);
for (const { file, line, message, hint } of problems) {
    const where = line ? `${file}:${String(line)}` : file;
    console.error(`${where}  ${hint ? "Hint: " : ""}${message}`);
}
const faults = problems.filter((p) => !p.hint);
if (faults.length > 0) {
    console.error(`\n${String(faults.length)} problem(s) in the docs.`);
    process.exitCode = 1;
}
else {
    console.log("Docs hold: links and anchors, written paths, page types, decision records, no orphans, no run headings.");
}
